import {buildElectricalArchitecture,connectorSelections,electricalKinds,electricalBuildCsv} from './electrical-architecture.js';
import {buildElectricalProgram,electricalProgramForItem,runElectricalCheck} from './electrical-program.js';
import {retainFile} from './file-delivery.js';

const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const num=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const link=(id,label)=>'<button type="button" class="ed-link" data-electrical-open-part="'+esc(id)+'">'+esc(label)+' ↗</button>';
const arr=v=>Array.isArray(v)?v:v&&typeof v==='object'?Object.values(v):v==null?[]:[v];
const fieldLabel=k=>{const units=[['AperMM2','A/mm²'],['Mbps','Mbit/s'],['Kbps','kbit/s'],['Gbps','Gbit/s'],['MM2','mm²'],['Ohm','Ω'],['Bytes','bytes'],['Kg','kg'],['Hz','Hz'],['MB','MB'],['Ms','ms'],['Us','µs'],['V','V'],['W','W'],['M','m'],['S','s'],['H','h']];let unit='';for(const [suffix,display]of units)if(k.endsWith(suffix)){k=k.slice(0,-suffix.length);unit=' ('+display+')';break;}const label=k.replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/([A-Z]+)([A-Z][a-z])/g,'$1 $2').replace(/([a-z])([0-9])/g,'$1 $2');return label.charAt(0).toUpperCase()+label.slice(1)+unit;};
const plain=v=>v==null?'':Array.isArray(v)?v.map(plain).join(', '):typeof v==='object'?Object.entries(v).map(([k,x])=>fieldLabel(k)+': '+plain(x)).join(' · '):typeof v==='boolean'?v?'Yes':'No':typeof v==='number'?(Number.isFinite(v)?v.toLocaleString('en-US',{maximumSignificantDigits:6}):'Invalid numeric value'):String(v);
const table=(caption,heads,rows)=>'<div class="ed-table-scroll" tabindex="0"><table class="ed-table"><caption>'+esc(caption)+'</caption><thead><tr>'+heads.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((x,i)=>'<'+(i?'td':'th scope="row"')+'>'+x+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table></div>';
const phaseNotes={
 A:['Define the electrical architecture','Allocate command authority, timing, housekeeping, payload isolation and all source/load interfaces. Establish a buildable interconnect concept before packaging is frozen.'],
 B:['Control the preliminary interface baseline','Inspect the box and card architecture, connector choices, source/load limits, harness schedule and verification methods. The PDR package includes how each interface will be demonstrated.'],
 C:['Develop and verify the interfaces','Develop flight-like cards, adapters and harnesses against the same pin/net register. Verify electrical limits and power protection before next-level integration.'],
 D:['Integrate with evidence','Inspect connector identity and workmanship, measure continuity and isolation before mating, then establish a powered functional baseline before and after environmental exposure.'],
 E:['Operate the protected control plane','Spacecraft command, time and engineering telemetry remain separate from customer traffic. Follow the actual command/housekeeping state and maintain configuration-controlled interface records.'],
 F:['Preserve command and final records','Retain commanding, time and engineering telemetry through passivation and disposal. Reconcile final data and archive the actual hardware, software and test configuration.']
};
function sourceLinks(graph,ids){return [...new Set(ids||[])].map(id=>graph.sources[id]).filter(Boolean).map(s=>s.url?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗</a>':'<span>'+esc(s.title)+'</span>').join(' · ');}

function boxGroup(box){
 if(box.id==='pcdu')return 'pcdu';if(box.id==='avionics')return 'avionics';if(box.id==='recorder')return 'recorder';if(box.id==='egse')return 'egse';
 if(box.id.startsWith('fabric-'))return 'fabric';if(box.id.startsWith('compute-'))return 'payload';if(box.id.startsWith('solar-root-'))return 'array';if(box.id.startsWith('battery-'))return 'battery';
 if(box.id==='sband-radio')return 'radio';if(box.id.startsWith('sband-patch-'))return 'antenna';if(/^(ka|optical)-/.test(box.id))return 'terminals';return 'subsystems';
}
const placements={array:[24,56,'Solar sources'],battery:[24,158,'Battery packs'],pcdu:[24,260,'Power conditioning'],egse:[24,362,'Ground checkout interface'],avionics:[316,56,'Flight avionics & GNSS'],fabric:[316,158,'Payload fabric'],recorder:[316,260,'Payload recorder'],radio:[316,362,'Command radio'],subsystems:[608,56,'Sensors & actuator interfaces'],payload:[608,158,'Compute trays'],terminals:[608,260,'Service terminals'],antenna:[608,362,'S-band antennas']};
export function electricalBlockDiagram(graph,kind='control'){
 const groups=new Map();for(const box of graph.boxes){const id=boxGroup(box);if(!groups.has(id))groups.set(id,[]);groups.get(id).push(box);}
 const edges=new Map();for(const h of graph.harnesses.filter(h=>h.kind===kind)){const from=boxGroup(graph.boxById[h.fromBoxId]),to=boxGroup(graph.boxById[h.toBoxId]),key=from+'>'+to;if(from===to)continue;const edge=edges.get(key)||{from,to,count:0,ids:[]};edge.count+=h.quantity;edge.ids.push(h.id);edges.set(key,edge);}
 const active=new Set([...edges.values()].flatMap(e=>[e.from,e.to])),color=electricalKinds[kind]?.color||'#75c8cb';
 const paths=[...edges.values()].map((e,i)=>{const a=placements[e.from],b=placements[e.to];if(!a||!b)return '';const same=a[0]===b[0],right=b[0]>a[0],x1=a[0]+(same?220:right?220:0),x2=b[0]+(same?220:right?0:220),y1=a[1]+33,y2=b[1]+33,lane=same?a[0]+238+(i%3)*8:(x1+x2)/2+((i%3)-1)*9,path='M'+x1+' '+y1+'H'+lane+'V'+y2+'H'+x2;return '<path class="ed-wire ed-wire-'+kind+'" d="'+path+'" style="--flow:'+color+'"><title>'+esc(e.ids.join(', '))+' · '+e.count+' assemblies</title></path>';}).join('');
 const nodes=[...groups.entries()].map(([id,boxes])=>{const [x,y,label]=placements[id],count=boxes.length,live=active.has(id),wbss=[...new Set(boxes.map(b=>b.wbs))],subtitle=(count>1?count+' boxes · ':'')+(wbss.length>2?wbss.length+' WBS groups':wbss.join(' / '));return '<g class="ed-node'+(live?' is-connected':'')+'" data-electrical-open-part="'+esc(boxes[0].itemId)+'" role="button" tabindex="0" aria-label="Open '+esc(label)+' in Parts navigator"><rect x="'+x+'" y="'+y+'" width="220" height="66" rx="7"/><text x="'+(x+110)+'" y="'+(y+26)+'">'+esc(label)+'</text><text class="ed-svg-sub" x="'+(x+110)+'" y="'+(y+47)+'">'+esc(subtitle)+'</text></g>';}).join('');
 return '<svg class="ed-block-diagram" viewBox="0 0 852 456" role="group" aria-label="Electrical box diagram. '+esc(electricalKinds[kind]?.label)+'. Boxes are grouped by function; the harness schedule retains each endpoint."><text class="ed-svg-zone" x="24" y="26">SOURCES & INTEGRATION</text><text class="ed-svg-zone" x="316" y="26">CONTROL & DATA HANDLING</text><text class="ed-svg-zone" x="608" y="26">PAYLOAD & SUBSYSTEMS</text>'+paths+nodes+'</svg>';
}

export function electricalCardDiagram(graph,selectedId=null){
 const cards=graph.cards.filter(c=>!c.external),external=graph.cards.filter(c=>c.external),cols=3,w=260,height=110,rowCount=Math.ceil(cards.length/cols),baseY=44;
 return '<div class="ed-card-diagram"><p class="ed-eyebrow">08.01 · FUNCTIONAL CARD ALLOCATION</p><svg viewBox="0 0 848 '+(baseY+rowCount*height+40)+'" role="group" aria-label="Flight avionics cards connected to the common power, clock, reset and data backplane">'+
 '<path d="M18 27H830" class="ed-backplane"/><text x="424" y="18" class="ed-svg-zone" text-anchor="middle">PROTECTED POWER · CLOCK / RESET · COMMAND / HOUSEKEEPING</text>'+
 cards.map((c,i)=>{const x=24+(i%cols)*282,y=baseY+Math.floor(i/cols)*height;return '<g class="ed-card'+(selectedId===c.itemId?' is-selected':'')+'" data-electrical-open-part="'+esc(c.itemId)+'" role="button" tabindex="0" aria-label="Open '+esc(c.label)+'"><path d="M'+(x+16)+' '+y+'V27" class="ed-card-trace"/><rect x="'+x+'" y="'+y+'" width="'+w+'" height="86" rx="6"/><text x="'+(x+14)+'" y="'+(y+25)+'">'+esc(c.label)+'</text><text class="ed-svg-sub" x="'+(x+14)+'" y="'+(y+46)+'">'+esc(c.wbs)+' · '+num(c.massKg)+' kg · '+num(c.powerW)+' W</text><text class="ed-svg-sub" x="'+(x+14)+'" y="'+(y+66)+'">'+esc(c.interfaces[0])+'</text></g>';}).join('')+'</svg>'+(external.length?'<div class="ed-actions"><span>External RF interface:</span>'+external.map(c=>link(c.itemId,c.label+' · '+num(c.massKg)+' kg · '+num(c.powerW)+' W')).join('')+'</div>':'')+'<p class="ed-muted">Functional design of the workbench avionics suite. The card masses and loads divide the existing 12 kg / 45 W allocation. This is a project implementation, not a vendor’s internal circuit drawing.</p></div>';
}

function harnessTable(graph,hs){
 return table('Harness build schedule · current configuration',['Assembly / quantity','Source → destination','Interface allocation','Route / build length','Mating interfaces'],hs.map(a=>[
 '<strong>'+esc(a.id)+'</strong><small>'+esc(electricalKinds[a.kind]?.label)+' · '+a.quantity+' installed</small>'+link(a.itemId,a.wbs+' · Part view')+'<button type="button" class="ed-link" data-electrical-inspect-harness="'+esc(a.id)+'">Wiring & build details</button>',
 esc(graph.boxById[a.fromBoxId]?.label)+'<small>'+esc(a.fromPortId)+'</small> → '+esc(graph.boxById[a.toBoxId]?.label)+'<small>'+esc(a.toPortId)+'</small>',
 a.kind==='power'?num(a.voltageV)+' V · '+num(a.currentA)+' A per branch<small>'+esc(a.wire.awg)+' AWG · '+num(a.voltageDropV,3)+' V predicted drop</small>':a.kind==='data'?num(a.rateMbps/1000)+' Gbit/s<small>'+esc(a.wire.construction)+'</small>':a.kind==='control'?num(a.rateMbps)+' Mbit/s<small>SpaceWire Type A · LVDS</small>':'50 Ω coax<small>RF path and continuous shield</small>',
 num(a.routeLengthM)+' m / '+num(a.cutLengthM)+' m<small>Minimum bend '+num(a.bendRadiusM*1000,1)+' mm · '+num(a.slackFraction*100,0)+'% service allowance</small>',
 link(graph.portById[a.fromPortId]?.connectorItemId,connectorSelections[a.connectorTypeId]?.label||a.connectorTypeId)
 ]));
}
function wiringDetails(graph,a){
 const c=connectorSelections[a.connectorTypeId];
 return '<details class="ed-build-detail"><summary>'+esc(a.id)+' · '+esc(a.label)+' <span>'+num(a.quantity,0)+' assemblies</span></summary><div class="arch-pad"><p>'+esc(a.wire.construction)+'</p><dl class="ed-specs"><div><dt>Source port</dt><dd>'+esc(a.fromPortId)+'</dd></div><div><dt>Destination port</dt><dd>'+esc(a.toPortId)+'</dd></div><div><dt>Cut length per assembly</dt><dd>'+num(a.cutLengthM)+' m</dd></div><div><dt>Minimum bend</dt><dd>'+num(a.bendRadiusM*1000)+' mm</dd></div></dl><p>'+esc(a.shieldTermination)+'</p><p>'+esc(a.strainRelief)+'</p><p>'+esc(a.notes)+'</p></div>'+table('Proposed point-to-point wiring / optical polarity',['From contact','To contact','Net','Construction'],a.pinout.map(p=>[esc(p.from),esc(p.to),esc(p.net),esc(p.conductor)]))+'<div class="arch-pad"><h4>Procurement and mating definition</h4><p>'+esc(c.procurement)+'</p><p class="ed-muted">'+esc(c.qualification)+'</p><p class="ed-source-line">'+sourceLinks(graph,a.sourceIds)+'</p></div></details>';
}
function harnessRegister(graph,hs){
 return '<div class="ed-harness-register"><div class="ed-harness-filter"><label>Find an interface<input type="search" data-electrical-harness-search placeholder="Harness ID, equipment, power or data…"></label><span data-electrical-harness-count>'+Math.min(30,hs.length)+' of '+hs.length+' routes</span><button type="button" data-electrical-harness-page="previous" disabled>Previous</button><button type="button" data-electrical-harness-page="next"'+(hs.length<=30?' disabled':'')+'>Next</button></div><div data-electrical-harness-rows>'+harnessTable(graph,hs.slice(0,30))+'</div><div data-electrical-harness-detail tabindex="-1"></div></div>';
}
function connectorTable(graph,details){
 return table('Connector procurement register',['Family / quantity','Mating definition','Selected electrical envelope','Evidence boundary'],details.map(d=>{const c=connectorSelections[d.typeId];return [link(d.itemId,c.label)+'<small>'+esc(c.manufacturer)+' · '+num(d.quantity,0)+' endpoint interfaces</small>',esc(c.arrangement)+'<small>'+esc(c.procurement)+'</small>',num(c.allocatedCurrentA)+' A project allocation<small>'+num(c.projectMaxV)+' V project ceiling</small>'+(Number.isFinite(c.supplierContactCurrentA)?'<small>'+num(c.supplierContactCurrentA)+' A supplier contact rating</small>':''),esc(c.qualification)+'<small>'+sourceLinks(graph,c.sourceIds)+'</small>'];}));
}

function requirementsMarkup(program,itemId=null){
 const view=itemId?electricalProgramForItem(program,itemId):program,requirements=arr(view?.requirements),plans=arr(view?.plans||view?.testPlans);
 return '<div class="ed-requirements"><header class="ed-section-head"><div><h3>Electrical requirements & verification</h3><p>Configuration-controlled allocations, verification methods and evidence obligations.</p></div><button type="button" class="btn" data-electrical-run>Run interface checks</button></header><div class="ed-run-options"><label>Power-load sensitivity<select data-electrical-load-scale><option value="1">Allocated load · 1×</option><option value="0.5">Half load · 0.5×</option><option value="1.25">Additional demand · 1.25×</option><option value="2">Double demand · 2×</option></select></label><label>Cable-length sensitivity<select data-electrical-length-scale><option value="1">Allocated route · 1×</option><option value="1.25">Additional routing · 1.25×</option><option value="1.5">Additional routing · 1.5×</option></select></label><small>Sensitivity changes the analysis case. The installed design and rendered route retain their baseline.</small></div><div data-electrical-result role="status" aria-live="polite"></div>'+
 table('Electrical capability and interface requirements',['Requirement','Allocation / criterion','Method and traceability','Evidence status'],requirements.map(r=>[
 '<strong>'+esc(r.id)+'</strong><small>'+esc(r.title||r.name||r.statement)+'</small>',esc(r.statement||r.description||'')+'<small>'+esc(plain(r.criteria||r.criterion||r.target||r.allocation))+'</small>',esc(arr(r.methods||r.verificationMethods||r.method).join(' · '))+'<small>'+esc(r.rationale||r.basis||'')+'</small><small>'+sourceLinks(program.graph,r.sourceIds)+'</small>','<span class="ed-status">Evidence '+esc(r.verificationStatus||'open')+'</span>'
 ]))+(plans.length?'<details class="ed-details"><summary>'+plans.length+' electrical verification activities</summary>'+plans.map(p=>'<article class="ed-plan"><h4>'+esc(p.title||p.name||p.id)+'</h4><p class="ed-eyebrow">'+esc(p.id)+' · '+esc(p.method||arr(p.methods).join(' / '))+' · '+esc(p.phase||'C / D')+'</p><p>'+esc(p.description||p.objective||'')+'</p><ol>'+arr(p.steps||p.procedure).map(step=>'<li>'+esc(typeof step==='string'?step:step.description||step.action||plain(step))+'</li>').join('')+'</ol><p><strong>Required evidence:</strong> '+esc(arr(p.evidenceRequired||p.artifacts||p.evidence).map(plain).join(' · '))+'</p></article>').join('')+'</details>':'')+'</div>';
}

function operatingState(s){return '<dl class="ed-live-readout"><div><dt>Avionics load</dt><dd>'+num((s.cdhKW||0)*1000,1)+' W</dd></div><div><dt>Ground commands</dt><dd>'+num(s.commandGoodputKbps||0,3)+' kbit/s</dd></div><div><dt>Housekeeping source</dt><dd>'+num(s.hkRateKbps||0,3)+' kbit/s</dd></div><div><dt>Engineering recorder</dt><dd>'+num(s.hkStoredMB||0)+' MB retained</dd></div></dl>';}

export function renderElectricalWorkspace(h,s={},phase='B'){
 const graph=buildElectricalArchitecture(h),program=buildElectricalProgram(h),stage=phaseNotes[phase]||phaseNotes.B;
 return '<section class="panel lowerpan ed-workspace" data-electrical-workspace data-electrical-item="" aria-label="Command and Data Handling engineering"><header class="panelhead"><h2>Command &amp; Data Handling</h2><span class="arch-stamp">Avionics & electrical interfaces</span></header><div class="arch-pad"><p class="ed-eyebrow">PHASE '+esc(phase)+' · '+esc(stage[0])+'</p><p>'+esc(stage[1])+'</p><p class="ed-scope">The protected spacecraft control plane connects avionics, power, sensors, actuators and radios. The payload network connects compute, storage and service terminals. Both use the interface register below; Flight Software defines the behavior running on the flight cards.</p><div data-electrical-live>'+operatingState(s)+'</div><div class="ed-diagram-controls"><div class="parts-choice" role="group" aria-label="Electrical diagram layer">'+['control','power','data','rf'].map(k=>'<button type="button" data-electrical-layer="'+k+'" aria-pressed="'+(k==='control')+'"><i style="--flow:'+electricalKinds[k].color+'"></i>'+esc(electricalKinds[k].label)+'</button>').join('')+'</div><span>'+graph.harnesses.length+' routes · '+num(graph.totalHarnessAssemblies,0)+' assemblies</span></div><div class="ed-diagram-scroll" data-electrical-diagram>'+electricalBlockDiagram(graph)+'</div><p class="ed-muted">Select a box to open its part page. Repeated equipment is grouped here; every endpoint and installed quantity remains in the build schedule. Solid amber denotes power, paired control dashes denote commands and housekeeping, packet groups denote payload traffic, and long dashes denote RF.</p><div class="ed-actions">'+link('flight:08.01','Avionics cards')+link('flight:07.05','Harness assemblies')+'<button type="button" class="ed-link" data-domain="data">Payload Data Handling ↗</button><button type="button" class="ed-link" data-domain="software">Flight Software ↗</button></div></div>'+
 '<details class="ed-details" open><summary>Avionics card architecture</summary>'+electricalCardDiagram(graph)+'</details><details class="ed-details"><summary>Harness build schedule · '+num(graph.totalCableLengthM)+' m of allocated cut length</summary>'+harnessRegister(graph,graph.harnesses)+'<div class="ed-actions"><button type="button" data-electrical-export="csv">Download harness build CSV ↓</button><button type="button" data-electrical-export="json">Download interface baseline JSON ↓</button></div>'+'</details><details class="ed-details"><summary>Connector procurement register</summary>'+connectorTable(graph,graph.connectorDetails)+'</details><div class="arch-pad">'+requirementsMarkup(program)+'<p class="ed-source-line">'+sourceLinks(graph,['el-nasa-avionics','el-gevs','el-nasa-workmanship','el-spacewire'])+'</p></div></section>';
}

export function electricalItemContext(h,record){
 const graph=buildElectricalArchitecture(h),id=typeof record==='string'?record:record?.id,wbs=typeof record==='object'?record.wbs:id?.startsWith('flight:')?id.slice(7):null;
 const group=graph.assemblies.find(a=>a.itemId===id),connector=graph.connectorDetails.find(c=>c.itemId===id),card=graph.cards.find(c=>c.itemId===id),boxes=graph.boxes.filter(b=>b.itemId===id),boxIds=new Set(boxes.map(b=>b.id));
 const item=id==='ground:egse-cable'?electricalProgramForItem(buildElectricalProgram(h),id):null;
 const harnesses=item?.harnesses|| (group?graph.harnesses.filter(a=>a.itemId===id):connector?graph.harnesses.filter(a=>a.connectorTypeId===connector.typeId&&a.parentWbs===connector.parentWbs):graph.harnesses.filter(a=>boxIds.has(a.fromBoxId)||boxIds.has(a.toBoxId)||(wbs==='07.05'&&a.parentWbs==='07.05')));
 return {graph,id,group,connector,card,boxes,harnesses,applicable:!!(item||group||connector||card||boxes.length||harnesses.length)};
}
export function renderPartElectrical(h,record){
 const c=electricalItemContext(h,record);if(!c.applicable)return '';
 const {graph,id,group,connector,card,harnesses}=c,program=buildElectricalProgram(h),showCards=!!card||id==='flight:08.01',type=connector&&connectorSelections[connector.typeId];
 const intro=card?card.purpose:group?'This harness assembly has a controlled source, destination, cable construction and mating pair. The installation schedule retains every instance.':connector?'Mating geometry, contact allocation and supplier evidence travel with the connector record. Each connected harness supplies its own pin/net assignment.':'This equipment’s electrical boundary includes the ports, power and signal connections listed below.';
 return '<section class="panel lowerpan ed-workspace ed-part-workspace" data-electrical-workspace data-electrical-item="'+esc(id)+'" aria-label="Electrical interfaces for '+esc(record.title)+'"><header class="panelhead"><h2>Electrical interfaces & capabilities</h2><span class="arch-stamp">'+esc(record.wbs||'')+'</span></header><div class="arch-pad"><p>'+esc(intro)+'</p>'+(card?'<p>'+esc(card.interfaces.join(' · '))+'</p>':'')+(type?'<h3>'+esc(type.label)+'</h3><p>'+esc(type.procurement)+'</p><p class="ed-muted">'+esc(type.qualification)+'</p>':'')+'<div class="ed-actions"><button type="button" data-electrical-rehearse>Show continuity & signal rehearsal</button><button type="button" data-electrical-export="csv">Harness build CSV ↓</button><button type="button" data-electrical-export="json">Electrical baseline JSON ↓</button></div></div>'+(showCards?electricalCardDiagram(graph,id):'')+(harnesses.length?harnessRegister(graph,harnesses):'<div class="arch-pad"><p>Card interfaces are internal to the avionics suite. '+link('flight:08.01','Open external box interfaces')+'</p></div>')+'<div class="arch-pad">'+requirementsMarkup(program,id)+'<p class="ed-source-line">'+sourceLinks(graph,[...new Set([...(card?.sourceIds||[]),...(type?.sourceIds||[]),...harnesses.flatMap(a=>a.sourceIds)])])+'</p></div></section>';
}

export function electricalResultMarkup(run){
 const checks=[...arr(run.checks||run.results)],missing=arr(run.inputErrors||run.missingInputs||run.errors),failures=checks.filter(c=>c.within===false||c.pass===false||/shortfall|fail/.test(c.status||'')),blocked=run.ready===false||missing.length>0;
 return '<div class="ed-result '+(blocked||failures.length?'ed-review':'ed-pass')+'"><h4>'+esc(blocked?'Interface inputs require correction':run.title||'Interface analysis completed')+'</h4><p>'+esc(run.message||(blocked?'The case cannot run until the listed input errors are corrected.':failures.length?'The prediction identifies allocations that need design review.':'The executed checks are within the current allocations.'))+'</p>'+(checks.length?'<p>'+checks.length+' checks · '+failures.length+' predicted shortfalls</p>':'')+(missing.length?'<ul>'+missing.map(m=>'<li>'+esc(plain(m))+'</li>').join('')+'</ul>':'')+'<p class="ed-muted">Calculated and inspected design records are analysis evidence. Physical continuity, insulation, signal quality and environmental performance still require measurements on the as-built article.</p><small>'+esc(run.evidenceId)+' · '+esc(run.configurationId)+'</small><p><button type="button" data-electrical-export="result">Download this check record ↓</button></p></div>'+(checks.length?table('Interface analysis results',['Check','Predicted / criterion','Result','Basis'],checks.sort((a,b)=>Number(a.within!==false)-Number(b.within!==false)).map(c=>[esc(c.label||c.title||c.id),esc(plain(c.actual??c.value))+' '+esc(c.unit||'')+'<small>Criterion: '+esc(c.criterionText||plain(c.limit??c.maximum??c.expected))+'</small>','<span class="'+(c.within===false||c.pass===false?'ed-fail':'ed-pass')+'">'+esc(c.status||(c.within===false||c.pass===false?'Predicted shortfall':'Predicted within allocation'))+'</span>',esc(c.basis||c.description||'')])):'');
}
export function bindElectricalWorkspace(host,{hardware,onOpenPart,onRehearse}={}){
 const root=host.matches?.('[data-electrical-workspace]')?host:host.querySelector('[data-electrical-workspace]');if(!root)return ()=>{};
 const graph=buildElectricalArchitecture(hardware),program=buildElectricalProgram(hardware),itemId=root.dataset.electricalItem||null;
 const harnesses=itemId?electricalItemContext(hardware,itemId).harnesses:graph.harnesses;let page=0,query='',lastRun=null;
 function paintHarnesses(){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean),matches=harnesses.filter(a=>words.every(word=>[a.id,a.label,a.kind,a.fromPortId,a.toPortId,connectorSelections[a.connectorTypeId]?.label].join(' ').toLowerCase().includes(word)));page=Math.max(0,Math.min(page,Math.ceil(matches.length/30)-1));const rows=root.querySelector('[data-electrical-harness-rows]');if(!rows)return;rows.innerHTML=harnessTable(graph,matches.slice(page*30,(page+1)*30));root.querySelector('[data-electrical-harness-count]').textContent=(matches.length?page*30+1:0)+'–'+Math.min((page+1)*30,matches.length)+' of '+matches.length+' routes';root.querySelector('[data-electrical-harness-page="previous"]').disabled=page===0;root.querySelector('[data-electrical-harness-page="next"]').disabled=(page+1)*30>=matches.length;}
 const click=async event=>{
  const target=event.target.closest('[data-electrical-layer],[data-electrical-run],[data-electrical-export],[data-electrical-rehearse],[data-electrical-open-part],[data-electrical-inspect-harness],[data-electrical-harness-page]');if(!target||!root.contains(target))return;
  if(target.dataset.electricalOpenPart){if(onOpenPart){event.stopPropagation();onOpenPart(target.dataset.electricalOpenPart);}return;}
  event.stopPropagation();
  if(target.dataset.electricalHarnessPage){page+=target.dataset.electricalHarnessPage==='next'?1:-1;paintHarnesses();return;}
  if(target.dataset.electricalInspectHarness){const a=harnesses.find(h=>h.id===target.dataset.electricalInspectHarness),detail=root.querySelector('[data-electrical-harness-detail]');if(a&&detail){detail.innerHTML=wiringDetails(graph,a);detail.querySelector('details').open=true;detail.focus({preventScroll:true});detail.scrollIntoView({block:'nearest',behavior:'instant'});}return;}
  if(target.dataset.electricalLayer){root.querySelectorAll('[data-electrical-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));root.querySelector('[data-electrical-diagram]').innerHTML=electricalBlockDiagram(graph,target.dataset.electricalLayer);return;}
  if(target.hasAttribute('data-electrical-run')){const output=root.querySelector('[data-electrical-result]');target.disabled=true;try{lastRun=await runElectricalCheck(program,{itemId,overrides:{loadScale:Number(root.querySelector('[data-electrical-load-scale]').value),lengthScale:Number(root.querySelector('[data-electrical-length-scale]').value)}});output.innerHTML=electricalResultMarkup(lastRun);root.dataset.electricalRunStatus=lastRun.status||'complete';}catch(error){output.innerHTML='<p class="ed-fail">'+esc(error.message||error)+'</p>';}finally{target.disabled=false;}return;}
  if(target.hasAttribute('data-electrical-rehearse')){onRehearse?.();return;}
  if(target.dataset.electricalExport){const request=target.dataset.electricalExport,format=request==='csv'?'csv':'json',content=format==='csv'?electricalBuildCsv(graph):JSON.stringify(request==='result'?lastRun:{architecture:graph,program,lastAnalysis:lastRun},null,2),file=retainFile('electrical-'+request,new Blob([content],{type:format==='csv'?'text/csv;charset=utf-8':'application/json'}),'ODC-electrical-'+(request==='result'?'check-':'')+graph.configurationId.replace(/[^a-z0-9-]/gi,'-')+'.'+format);const a=document.createElement('a');a.href=file.url;a.download=file.name;a.click();}
 };
 const key=event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('g[data-electrical-open-part]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}};
 const input=event=>{if(event.target.hasAttribute('data-electrical-harness-search')){query=event.target.value;page=0;paintHarnesses();}};
 root.addEventListener('click',click);root.addEventListener('keydown',key);root.addEventListener('input',input);return ()=>{root.removeEventListener('click',click);root.removeEventListener('keydown',key);root.removeEventListener('input',input);};
}
export function updateElectricalWorkspace(host,s){const live=host.querySelector('[data-electrical-live]');if(live)live.innerHTML=operatingState(s);}
